                    introducao?: string;
                    /** @example Conteúdo completo... */
                    conteudo: string;
                    /** @example Conclusão... */
                    conclusao?: string;
                    /** @example true */
                    ativo?: boolean;
                    /** @example cmllb9lcp00006kd2sa7y88lb */
