                    /** @example Dra. Ana Veterinária */
                    vetNome?: string;
                    /**
                     * Format: binary
                     * @description Foto do veterinário (1 arquivo)
                     */
                    vetFoto?: string;
                    /** @example CRMV-SP 12345 */
                    vetCrmv?: string;
                    /** @example 11999998888 */
                    vetContatoValor?: string;
                    /**
                     * @example WHATSAPP
                     * @enum {string}
                     */
                    vetContatoTipo?: "WHATSAPP" | "EMAIL" | "INSTAGRAM";
                    /** @description JSON string com traduções por locale (en-US | en-GB | es-419). Pode incluir slug por idioma. Ex.: {"en-US":{"titulo":"...","slug":"how-to-care"}} */
